    /** The player's period of [pitch] (clamped to 0..[PITCH_MAX]): ((DIV[f] + 2^(7+o)) >> (8+o)) - 1, at most [PERIOD_MAX]. */
    fun period(pitch: Int): Int {
        val p = pitch.coerceIn(0, PITCH_MAX)
        val octave = p / PITCH_UNITS_PER_OCTAVE
        val f = p % PITCH_UNITS_PER_OCTAVE
        return minOf(PERIOD_MAX, ((DIV[f] + (1 shl (DIV_SHIFT - 1 + octave))) shr (DIV_SHIFT + octave)) - 1)
    }

    /** The chip's frequency at [period]: [CLOCK] / (32 ([period] + 1)) Hz. */
    fun hz(period: Int): Double = CLOCK / (32.0 * (period + 1))

